    all_names = [cp["name"] for cp in existing_cheatpaths]
    if include_cwd:
        all_names.append("cwd")
    max_name_len = max([len(n) for n in all_names]) if all_names else 0
    # For each cheatpath in original order, print
    for cp in existing_cheatpaths:
        name = cp["name"]
        raw_path = cp.get("path","")
        expanded = expand_path(raw_path)
        # name with colon
        name_colon = f"{name}:"
        # Determine padding: name_colon ljust to max_name_len+1 (including colon)
        name_colon_width = max_name_len + 1
        padded = name_colon.ljust(name_colon_width)
        # Then one space + path
        sys.stdout.write(f"{padded} {expanded}\n")

    if include_cwd:
        name = "cwd"
        name_colon = f"{name}:"
        name_colon_width = max_name_len + 1
        padded = name_colon.ljust(name_colon_width)
        sys.stdout.write(f"{padded} {found_dot_cheat}\n")

