def handle_update(cfg, filter_path=None):
    # Update git-backed cheatpaths by pulling latest changes
    # Original behavior: for each cheatpath that is a git repo, run git pull? It prints "<name>: <status>"
    # Status observed: "gitrepo: error (remote not found)" when repo has no remote, exit 1
    # "personal: skipped (not a git repository)" when path is not git repo
    # So it iterates over cheatpaths (filtered by path if provided) and tries to update.

    # Determine which cheatpaths to update
    cheatpaths_to_update = []
    for cp in cfg.get("cheatpaths", []):
        if filter_path and cp.get("name") != filter_path:
            continue
        cheatpaths_to_update.append(cp)

    # For each, check if path exists
    any_error = False
    for cp in cheatpaths_to_update:
        name = cp.get("name")
        raw_path = cp.get("path","")
        expanded = expand_path(raw_path)
        p = Path(expanded)
        if not p.exists() or not p.is_dir():
            # Skip? Original warned? For update, when path doesn't exist, it skipped? In earlier log, when work missing, update gave "personal: skipped (not a git repository)" etc. It still processed existing paths, but missing paths were warned earlier? Actually print_warnings would have printed warning for missing path separately.
            # We'll skip missing paths for update (they would have been warned already)
            continue
        # Check if .git dir exists
        git_dir = p / ".git"
        if not git_dir.exists():
            print(f"{name}: skipped (not a git repository)")
            continue
        # Try git pull
        try:
            result = subprocess.run(["git","-C", str(p), "pull", "--ff-only"], capture_output=True, text=True, timeout=30)
            if result.returncode != 0:
                # Determine error reason
                # If remote not found, print "error (remote not found)"
                # We can parse result.stderr for remote not found
                if "remote" in result.stderr.lower() or "not found" in result.stderr.lower() or "No remote" in result.stderr:
                    print(f"{name}: error (remote not found)")
                else:
                    print(f"{name}: error ({result.stderr.strip()})")
                any_error = True
            else:
                # Success? What does original print on success? Not observed. Probably prints updated or something.
                print(f"{name}: updated")
        except Exception as e:
            print(f"{name}: error ({e})")
            any_error = True

    if any_error:
        sys.exit(1)
    sys.exit(0)

