        visual = os.environ.get("VISUAL")
        editor_env = os.environ.get("EDITOR")
        if visual:
            editor_val = visual
        elif editor_env:
            editor_val = editor_env
        else:
            editor_val = "EDITOR_PATH"
    else:
        editor_val = editor_override
    if pager_override is None:
        pager_env = os.environ.get("PAGER")
        if pager_env:
            pager_val = pager_env
        else:
            pager_val = "cat"
    else:
        pager_val = pager_override
    template = f"""---
# The editor to use with 'cheat -e <sheet>'. Overridden by $VISUAL or $EDITOR.
editor: {editor_val}

# Should 'cheat' always colorize output?
colorize: false

# Which 'chroma' colorscheme should be applied to the output?
# Options are available here:
#   https://github.com/alecthomas/chroma/tree/master/styles
style: monokai

# Which 'chroma' "formatter" should be applied?
# One of: "terminal", "terminal256", "terminal16m"
formatter: terminal256

# Through which pager should output be piped?
# 'less -FRX' is recommended on Unix systems
# 'more' is recommended on Windows
pager: {pager_val}

# The paths at which cheatsheets are available. Tags associated with a cheatpath
# are automatically attached to all cheatsheets residing on that path.
#
# Whenever cheatsheets share the same title (like 'tar'), the most local
# cheatsheets (those which come later in this file) take precedence over the
# less local sheets. This allows you to create your own "overides" for
# "upstream" cheatsheets.
#
# But what if you want to view the "upstream" cheatsheets instead of your own?
# Cheatsheets may be filtered by 'tags' in combination with the '--tag' flag.
# 
# Example: 'cheat tar --tag=community' will display the 'tar' cheatsheet that
# is tagged as 'community' rather than your own.
#
# Paths that come earlier are considered to be the most "global", and paths
# that come later are considered to be the most "local". The most "local" paths
# take precedence.
#
# See: https://github.com/cheat/cheat/blob/master/doc/cheat.1.md#cheatpaths
cheatpaths:

  # Cheatsheets that are tagged "personal" are stored here by default:
  - name: personal
    path: {cheatsheets_base / "personal"}
    tags: [ personal ]
    readonly: false

  # Cheatsheets that are tagged "work" are stored here by default:
  - name: work
    path: {cheatsheets_base / "work"}
    tags: [ work ]
    readonly: false

  # Community cheatsheets (https://github.com/cheat/cheatsheets):
  # To install: git clone https://github.com/cheat/cheatsheets {cheatsheets_base / "community"}
  #- name: community
  #  path: {cheatsheets_base / "community"}
  #  tags: [ community ]
  #  readonly: true

  # You can also use glob patterns to automatically load cheatsheets from all
  # directories that match.
  #
  # Example: overload cheatsheets for projects under ~/src/github.com/example/*/
  #- name: example-projects
  #  path: ~/src/github.com/example/**/.cheat
  #  tags: [ example ]
  #  readonly: true
"""
    return template

def load_config_or_install():
    existing_path, candidate_path = get_config_path()
    if existing_path is None:
        decision = should_create_config_from_prompt()
        if decision == "eof_first":
            sys.stderr.write("failed to create config: failed to prompt: EOF\n")
            sys.exit(1)
        if decision == "no":
            sys.exit(0)
        decision2 = should_clone_community()
        if decision2 == "eof_second":
            sys.stderr.write("failed to run installer: failed to prompt: failed to prompt: EOF\n")
            sys.exit(1)
        if decision2 == "yes":
            dest = candidate_path.parent / "cheatsheets" / "community"
            sys.stdout.write(f"Cloning community cheatsheets to {dest}.\n")
            sys.stdout.flush()
            try:
                dest.parent.mkdir(parents=True, exist_ok=True)
                result = subprocess.run(["git","clone","https://github.com/cheat/cheatsheets.git", str(dest)], capture_output=True, text=True, timeout=10)
                if result.returncode != 0:
                    if dest.exists():
                        shutil.rmtree(dest, ignore_errors=True)
                    err = result.stderr.strip() or result.stdout.strip()
                    sys.stderr.write(f"failed to run installer: failed to clone cheatsheets: failed to clone cheatsheets: {err}\n")
                    sys.exit(1)
            except subprocess.TimeoutExpired:
                sys.stderr.write("failed to run installer: failed to clone cheatsheets: failed to clone cheatsheets: Get \"https://github.com/cheat/cheatsheets.git/info/refs?service=git-upload-pack\": dial tcp 140.82.114.4:443: i/o timeout\n")
                sys.exit(1)
            except FileNotFoundError:
                sys.stderr.write("failed to run installer: failed to clone cheatsheets: failed to clone cheatsheets: git not found\n")
                sys.exit(1)
        config_content = generate_init_config(base_dir=candidate_path.parent)
        candidate_path.parent.mkdir(parents=True, exist_ok=True)
        (candidate_path.parent / "cheatsheets" / "personal").mkdir(parents=True, exist_ok=True)
        (candidate_path.parent / "cheatsheets" / "work").mkdir(parents=True, exist_ok=True)
        open(candidate_path, "w").write(config_content)
        sys.stdout.write(f"Created config file: {candidate_path}\nPlease read this file for advanced configuration information.\n")
        sys.exit(0)
    try:
        text = open(existing_path).read()
        cfg = parse_config_simple(text)
    except Exception as e:
        sys.stderr.write(f"failed to load config: {e}\n")
        sys.exit(1)
    if "editor" not in cfg or not cfg["editor"]:
        sys.stderr.write("failed to load config: no editor set\n")
        sys.exit(1)
    if "cheatpaths" not in cfg or not cfg["cheatpaths"]:
        sys.stderr.write("failed to load config: config error: no cheatpaths specified\n")
        sys.exit(1)
    for cp in cfg["cheatpaths"]:
        if "name" not in cp or not cp["name"]:
            sys.stderr.write("failed to load config: config error: cheatpath name cannot be empty\n")
            sys.exit(1)
    return existing_path, cfg

def expand_path(p):
    return os.path.expanduser(p)

def collect_sheets(cfg, filter_path=None, filter_tag=None):
    sheets = []
    for cp in cfg.get("cheatpaths", []):
        name = cp.get("name")
        raw_path = cp.get("path","")
        if not raw_path:
            continue
        expanded = expand_path(raw_path)
        path_exists = Path(expanded).exists() and Path(expanded).is_dir()
        if filter_path and name != filter_path:
            continue
        if not path_exists:
            continue
        base = Path(expanded)
        for root, dirs, files in os.walk(base):
            for f in files:
                full = Path(root) / f
                rel = full.relative_to(base)
                title = str(rel).replace(os.sep, '/')
                try:
                    content = full.read_text(errors='ignore')
                except:
                    continue
                cp_tags = cp.get("tags", []) or []
                if isinstance(cp_tags, str):
                    cp_tags = [cp_tags]
                frontmatter_tags = []
                syntax = None
                remaining_content = content
                if content.startswith('---'):
                    lines = content.splitlines()
                    if len(lines) >= 2 and lines[0].strip() == '---':
                        end_idx = None
                        for i in range(1, len(lines)):
                            if lines[i].strip() == '---':
                                end_idx = i
                                break
                        if end_idx is not None:
                            fm_text = "\n".join(lines[1:end_idx])
                            for fm_line in fm_text.splitlines():
                                fm_line_stripped = fm_line.strip()
                                if not fm_line_stripped or fm_line_stripped.startswith('#'):
                                    continue
                                if fm_line_stripped.startswith('tags:'):
                                    v = fm_line_stripped.split(':',1)[1].strip()
                                    if v.startswith('[') and v.endswith(']'):
                                        inner = v[1:-1].strip()
                                        if inner:
                                            parts = [p.strip() for p in inner.split(',')]
                                            for p in parts:
                                                if (p.startswith('"') and p.endswith('"')) or (p.startswith("'") and p.endswith("'")):
                                                    p=p[1:-1]
                                                frontmatter_tags.append(p)
                                elif fm_line_stripped.startswith('syntax:'):
                                    v = fm_line_stripped.split(':',1)[1].strip()
                                    if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                                        v=v[1:-1]
                                    syntax = v
                            remaining_content = "\n".join(lines[end_idx+1:])
                all_tags = []
                all_tags.extend(cp_tags)
                all_tags.extend(frontmatter_tags)
                sheets.append({
                    "title": title,
                    "file_path": str(full),
                    "tags": all_tags,
                    "cheatpath_name": name,
                    "cheatpath_path": expanded,
                    "readonly": bool(cp.get("readonly", False)),
                    "syntax": syntax,
                    "content": remaining_content,
                    "full_content": content,
                })
    cwd = Path.cwd()
    current = cwd
    found_dot_cheat = None
    while True:
        dot = current / ".cheat"
        if dot.exists() and dot.is_dir():
            found_dot_cheat = dot
            break
        if current.parent == current:
            break
        current = current.parent
    if found_dot_cheat:
        dot_path = str(found_dot_cheat)
        dot_name = "cwd"
        if (filter_path is None) or (filter_path == dot_name):
            base = found_dot_cheat
            for root, dirs, files in os.walk(base):
                for f in files:
                    full = Path(root) / f
                    rel = full.relative_to(base)
                    title = str(rel).replace(os.sep, '/')
                    try:
                        content = full.read_text(errors='ignore')
                    except:
                        continue
                    frontmatter_tags = []
                    syntax = None
                    remaining_content = content
                    if content.startswith('---'):
                        lines = content.splitlines()
                        if len(lines) >= 2 and lines[0].strip() == '---':
                            end_idx = None
                            for i in range(1, len(lines)):
                                if lines[i].strip() == '---':
                                    end_idx = i
                                    break
                            if end_idx is not None:
                                fm_text = "\n".join(lines[1:end_idx])
                                for fm_line in fm_text.splitlines():
                                    fm_line_stripped = fm_line.strip()
                                    if not fm_line_stripped or fm_line_stripped.startswith('#'):
                                        continue
                                    if fm_line_stripped.startswith('tags:'):
                                        v = fm_line_stripped.split(':',1)[1].strip()
                                        if v.startswith('[') and v.endswith(']'):
                                            inner = v[1:-1].strip()
                                            if inner:
                                                parts = [p.strip() for p in inner.split(',')]
                                                for p in parts:
                                                    if (p.startswith('"') and p.endswith('"')) or (p.startswith("'") and p.endswith("'")):
                                                        p=p[1:-1]
                                                    frontmatter_tags.append(p)
                                    elif fm_line_stripped.startswith('syntax:'):
                                        v = fm_line_stripped.split(':',1)[1].strip()
                                        if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                                            v=v[1:-1]
                                        syntax = v
                                remaining_content = "\n".join(lines[end_idx+1:])
                    all_tags = []
                    all_tags.extend(frontmatter_tags)
                    sheets.append({
                        "title": title,
                        "file_path": str(full),
                        "tags": all_tags,
                        "cheatpath_name": dot_name,
                        "cheatpath_path": dot_path,
                        "readonly": False,
                        "syntax": syntax,
                        "content": remaining_content,
                        "full_content": content,
                    })
    if filter_tag:
        filtered = []
        for s in sheets:
            if filter_tag in s["tags"]:
                filtered.append(s)
        sheets = filtered
    return sheets

