def handle_view_sheet(sheet, cfg, colorize=False):
    content = sheet["content"]
    effective_colorize = colorize or cfg.get("colorize", False)
    if effective_colorize:
        cfg_style = cfg.get("style","monokai")
        cfg_formatter = cfg.get("formatter","terminal256")
        syntax = sheet.get("syntax")
        try:
            from pygments import highlight
            from pygments.lexers import get_lexer_by_name, guess_lexer
            from pygments.formatters import Terminal256Formatter, TerminalFormatter
            from pygments.lexers import TextLexer
            code = content
            if not code.endswith('\n'):
                code = code + '\n'
            lexer = None
            if syntax:
                try:
                    lexer = get_lexer_by_name(syntax, stripall=False)
                except:
                    lexer = None
            if lexer is None:
                try:
                    lexer = guess_lexer(code)
                except:
                    lexer = TextLexer()
            if cfg_formatter == "terminal":
                formatter = TerminalFormatter(style=cfg_style)
            elif cfg_formatter == "terminal256":
                formatter = Terminal256Formatter(style=cfg_style)
            elif cfg_formatter == "terminal16m":
                from pygments.formatters import TerminalTrueColorFormatter
                formatter = TerminalTrueColorFormatter(style=cfg_style)
            else:
                formatter = Terminal256Formatter(style=cfg_style)
            highlighted = highlight(code, lexer, formatter)
            # To better match original chroma output for monokai, we attempt to adjust colors?
            # Original chroma for bash: comment # title -> 242, rest 231
            # Pygments monokai gives 245 for comment, 255 for echo, etc. We will try to map 245->242 and 255->231 for terminal256 monokai to match more closely
            if cfg_style == "monokai" and cfg_formatter == "terminal256":
                # Replace \x1b[38;5;245m (pygments comment) with 242m
                highlighted = highlighted.replace("\x1b[38;5;245m", "\x1b[38;5;242m")
                # Pygments uses 255 for some tokens, chroma uses 231 for almost everything else
                highlighted = highlighted.replace("\x1b[38;5;15m", "\x1b[38;5;231m")
                highlighted = highlighted.replace("\x1b[38;5;255m", "\x1b[38;5;231m")
                # Also replace 37 etc?
                highlighted = highlighted.replace("\x1b[37m", "\x1b[38;5;231m")
                highlighted = highlighted.replace("\x1b[39m", "\x1b[0m")
            sys.stdout.write(highlighted)
            return
        except Exception:
            pass
        out_lines = []
        for line in content.splitlines():
            if line.lstrip().startswith('#'):
                out_lines.append(f"\x1b[38;5;242m{line}\x1b[0m\x1b[38;5;231m\x1b[0m")
            else:
                if line == "":
                    out_lines.append(f"\x1b[38;5;231m\x1b[0m")
                else:
                    out_lines.append(f"\x1b[38;5;231m{line}\x1b[0m")
        sys.stdout.write("\n".join(out_lines) + "\n")
        return
    sys.stdout.write(content)
    if content and not content.endswith('\n'):
        sys.stdout.write('\n')

def handle_search(sheets, cfg, phrase, colorize=False, regex=False):
    flags = 0
    if not regex:
        flags = re.IGNORECASE
    try:
        pattern = re.compile(phrase, flags)
    except re.error as e:
        sys.stderr.write(f"failed to search: {e}\n")
        sys.exit(1)
    matching_sheets = []
    for s in sheets:
        if pattern.search(s["content"]):
            matching_sheets.append(s)
    matching_sheets_sorted = sorted(matching_sheets, key=lambda x: x["title"].lower())
    for s in matching_sheets_sorted:
        tags_str = ",".join(s["tags"])
        if colorize or cfg.get("colorize", False):
            sys.stdout.write(f"{s['title']} \x1b[2m({tags_str})\x1b[0m\n")
            for line in s["content"].splitlines():
                if line.lstrip().startswith('#'):
                    colored = f"\x1b[38;5;242m{line}\x1b[0m\x1b[38;5;231m\x1b[0m"
                else:
                    colored = f"\x1b[38;5;231m{line}\x1b[0m" if line else f"\x1b[38;5;231m\x1b[0m"
                sys.stdout.write(f"\t{colored}\n")
        else:
            sys.stdout.write(f"{s['title']} ({tags_str})\n")
            for line in s["content"].splitlines():
                sys.stdout.write(f"\t{line}\n")

def handle_update(cfg, filter_path=None):
    cheatpaths_to_update = []
    for cp in cfg.get("cheatpaths", []):
        if filter_path and cp.get("name") != filter_path:
            continue
        cheatpaths_to_update.append(cp)
    any_error = False
    for cp in cheatpaths_to_update:
        name = cp.get("name")
        raw_path = cp.get("path","")
        expanded = expand_path(raw_path)
        p = Path(expanded)
        if not p.exists() or not p.is_dir():
            continue
        git_dir = p / ".git"
        if not git_dir.exists():
            print(f"{name}: skipped (not a git repository)")
            continue
        try:
            result = subprocess.run(["git","-C", str(p), "pull", "--ff-only"], capture_output=True, text=True, timeout=30)
            if result.returncode != 0:
                if "remote" in result.stderr.lower() or "not found" in result.stderr.lower() or "no remote" in result.stderr.lower() or "no such remote" in result.stderr.lower():
                    print(f"{name}: error (remote not found)")
                else:
                    print(f"{name}: error ({result.stderr.strip()})")
                any_error = True
            else:
                print(f"{name}: updated")
        except Exception as e:
            print(f"{name}: error ({e})")
            any_error = True
    if any_error:
        sys.exit(1)
    sys.exit(0)

def main():
    args = sys.argv[1:]
    if "-h" in args or "--help" in args:
