def prompt_yes_no(prompt_text):
    try:
        sys.stdout.write(prompt_text)
        sys.stdout.flush()
        line = sys.stdin.readline()
        if not line:
            raise EOFError
        return line.strip()
    except EOFError:
        raise

def should_create_config_from_prompt():
    try:
        ans = prompt_yes_no("A config file was not found. Would you like to create one now? [Y/n]: ")
    except EOFError:
        return "eof_first"
    trimmed = ans.strip()
    if trimmed == "" or trimmed.lower() == "y":
        return "yes"
    else:
        return "no"

def should_clone_community():
    try:
        ans = prompt_yes_no("Would you like to download the community cheatsheets? [Y/n]: ")
    except EOFError:
        return "eof_second"
    trimmed = ans.strip()
    if trimmed == "" or trimmed.lower() == "y":
        return "yes"
    else:
        return "no"

def generate_init_config(base_dir=None, editor_override=None, pager_override=None):
    if base_dir is None:
        existing, candidate = get_config_path()
        if candidate is None:
            if existing:
                config_dir = existing.parent
            else:
                home = os.environ.get("HOME", str(Path.home()))
                config_dir = Path(home) / ".config" / "cheat"
        else:
            config_dir = candidate.parent
    else:
        config_dir = Path(base_dir)
    cheatsheets_base = config_dir / "cheatsheets"
