def handle_update(cfg, filter_path=None):
    cheatpaths_to_update = []
    for cp in cfg.get("cheatpaths", []):
        if filter_path and cp.get("name") != filter_path:
            continue
        cheatpaths_to_update.append(cp)
    any_error = False
    for cp in cheatpaths_to_update:
        name = cp.get("name")
        raw_path = cp.get("path","")
        expanded = expand_path(raw_path)
        p = Path(expanded)
        if not p.exists() or not p.is_dir():
            continue
        git_dir = p / ".git"
        if not git_dir.exists():
            print(f"{name}: skipped (not a git repository)")
            continue
        try:
            result = subprocess.run(["git","-C", str(p), "pull", "--ff-only"], capture_output=True, text=True, timeout=30)
            if result.returncode != 0:
                if "remote" in result.stderr.lower() or "not found" in result.stderr.lower() or "no remote" in result.stderr.lower() or "no such remote" in result.stderr.lower():
                    print(f"{name}: error (remote not found)")
                else:
                    print(f"{name}: error ({result.stderr.strip()})")
                any_error = True
            else:
                print(f"{name}: updated")
        except Exception as e:
            print(f"{name}: error ({e})")
            any_error = True
    if any_error:
        sys.exit(1)
    sys.exit(0)

def main():
    args = sys.argv[1:]
    if "-h" in args or "--help" in args:
        print("""cheat allows you to create and view interactive cheatsheets on the
command-line. It was designed to help remind *nix system administrators of
options for commands that they use frequently, but not frequently enough to
remember.

Usage:
  cheat [cheatsheet] [flags]

Examples:
  To initialize a config file:
    mkdir -p ~/.config/cheat && cheat --init > ~/.config/cheat/conf.yml

  To view the tar cheatsheet:
    cheat tar

  To edit (or create) the foo cheatsheet:
    cheat -e foo

  To edit (or create) the foo/bar cheatsheet on the "work" cheatpath:
    cheat -p work -e foo/bar

  To view all cheatsheet directories:
    cheat -d

  To list all available cheatsheets:
    cheat -l

  To briefly list all cheatsheets whose titles match "apt":
    cheat -b apt

  To list all tags in use:
    cheat -T

  To list available cheatsheets that are tagged as "personal":
    cheat -l -t personal

  To search for "ssh" among all cheatsheets, and colorize matches:
    cheat -c -s ssh

  To search (by regex) for cheatsheets that contain an IP address:
    cheat -c -r -s '(?:[0-9]{1,3}\\.){3}[0-9]{1,3}'

  To remove (delete) the foo/bar cheatsheet:
    cheat --rm foo/bar

  To update all git-backed cheatpaths:
    cheat --update

  To view the configuration file path:
    cheat --conf

  To generate shell completions (bash, zsh, fish, powershell):
    cheat --completion bash

