            all_sheets = collect_sheets(cfg, filter_path=None, filter_tag=None)
            all_matching = [s for s in all_sheets if s["title"] == parsed["rm"]]
            if not all_matching:
                sys.stderr.write(f"No cheatsheet found for '{parsed['rm']}'.\n")
                sys.exit(2)
            # if filtered but not matching, still not found
            sys.stderr.write(f"No cheatsheet found for '{parsed['rm']}'.\n")
            sys.exit(2)
        most_local = matching[-1]
        if most_local["readonly"]:
            sys.stderr.write(f"cheatsheet '{parsed['rm']}' is read-only.\n")
            sys.exit(1)
        try:
            Path(most_local["file_path"]).unlink()
        except Exception as e:
            sys.stderr.write(f"failed to remove cheatsheet: {e}\n")
            sys.exit(1)
        sys.exit(0)

    if parsed["edit"]:
        if parsed["positional"]:
