                                            for p in parts:
                                                if (p.startswith('"') and p.endswith('"')) or (p.startswith("'") and p.endswith("'")):
                                                    p=p[1:-1]
                                                frontmatter_tags.append(p)
                                elif fm_line_stripped.startswith('syntax:'):
                                    v = fm_line_stripped.split(':',1)[1].strip()
                                    if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                                        v=v[1:-1]
                                    syntax = v
                            remaining_content = "\n".join(lines[end_idx+1:])
                all_tags = []
                all_tags.extend(cp_tags)
                all_tags.extend(frontmatter_tags)
                sheets.append({
                    "title": title,
                    "file_path": str(full),
                    "tags": all_tags,
                    "cheatpath_name": name,
                    "cheatpath_path": expanded,
                    "readonly": bool(cp.get("readonly", False)),
                    "syntax": syntax,
                    "content": remaining_content,
                    "full_content": content,
                })
    cwd = Path.cwd()
    current = cwd
    found_dot_cheat = None
    while True:
        dot = current / ".cheat"
        if dot.exists() and dot.is_dir():
            found_dot_cheat = dot
            break
        if current.parent == current:
            break
        current = current.parent
    if found_dot_cheat:
        dot_path = str(found_dot_cheat)
        dot_name = "cwd"
        if (filter_path is None) or (filter_path == dot_name):
            base = found_dot_cheat
            for root, dirs, files in os.walk(base):
                for f in files:
                    full = Path(root) / f
                    rel = full.relative_to(base)
                    title = str(rel).replace(os.sep, '/')
                    try:
                        content = full.read_text(errors='ignore')
                    except:
                        continue
                    frontmatter_tags = []
                    syntax = None
                    remaining_content = content
                    if content.startswith('---'):
                        lines = content.splitlines()
                        if len(lines) >= 2 and lines[0].strip() == '---':
                            end_idx = None
                            for i in range(1, len(lines)):
                                if lines[i].strip() == '---':
                                    end_idx = i
                                    break
                            if end_idx is not None:
                                fm_text = "\n".join(lines[1:end_idx])
                                for fm_line in fm_text.splitlines():
                                    fm_line_stripped = fm_line.strip()
                                    if not fm_line_stripped or fm_line_stripped.startswith('#'):
                                        continue
                                    if fm_line_stripped.startswith('tags:'):
                                        v = fm_line_stripped.split(':',1)[1].strip()
                                        if v.startswith('[') and v.endswith(']'):
                                            inner = v[1:-1].strip()
                                            if inner:
                                                parts = [p.strip() for p in inner.split(',')]
                                                for p in parts:
                                                    if (p.startswith('"') and p.endswith('"')) or (p.startswith("'") and p.endswith("'")):
                                                        p=p[1:-1]
                                                    frontmatter_tags.append(p)
                                    elif fm_line_stripped.startswith('syntax:'):
                                        v = fm_line_stripped.split(':',1)[1].strip()
                                        if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                                            v=v[1:-1]
                                        syntax = v
                                remaining_content = "\n".join(lines[end_idx+1:])
                    all_tags = []
                    all_tags.extend(frontmatter_tags)
                    sheets.append({
                        "title": title,
                        "file_path": str(full),
                        "tags": all_tags,
                        "cheatpath_name": dot_name,
                        "cheatpath_path": dot_path,
                        "readonly": False,
                        "syntax": syntax,
                        "content": remaining_content,
                        "full_content": content,
                    })
    if filter_tag:
        filtered = []
        for s in sheets:
            if filter_tag in s["tags"]:
                filtered.append(s)
        sheets = filtered
    return sheets

def print_warnings(cfg):
    for cp in cfg.get("cheatpaths", []):
        raw_path = cp.get("path","")
        if not raw_path:
            continue
        expanded = expand_path(raw_path)
        if not Path(expanded).exists() or not Path(expanded).is_dir():
            sys.stderr.write(f"WARNING: cheatpath '{raw_path}' does not exist, skipping\n")

def get_editor(cfg):
    visual = os.environ.get("VISUAL")
    editor_env = os.environ.get("EDITOR")
    if visual:
        return visual
    if editor_env:
        return editor_env
    return cfg.get("editor")

def handle_view_sheet(sheet, cfg, colorize=False):
    content = sheet["content"]
    effective_colorize = colorize or cfg.get("colorize", False)
    if effective_colorize:
        cfg_style = cfg.get("style","monokai")
        cfg_formatter = cfg.get("formatter","terminal256")
        syntax = sheet.get("syntax")
        try:
            from pygments import highlight
            from pygments.lexers import get_lexer_by_name, guess_lexer
            from pygments.formatters import Terminal256Formatter, TerminalFormatter
            from pygments.lexers import TextLexer
            code = content
            if not code.endswith('\n'):
                code = code + '\n'
            lexer = None
            if syntax:
                try:
                    lexer = get_lexer_by_name(syntax, stripall=False)
                except:
                    lexer = None
            if lexer is None:
                try:
                    lexer = guess_lexer(code)
                except:
                    lexer = TextLexer()
            if cfg_formatter == "terminal":
                formatter = TerminalFormatter(style=cfg_style)
            elif cfg_formatter == "terminal256":
                formatter = Terminal256Formatter(style=cfg_style)
            elif cfg_formatter == "terminal16m":
                from pygments.formatters import TerminalTrueColorFormatter
                formatter = TerminalTrueColorFormatter(style=cfg_style)
            else:
                formatter = Terminal256Formatter(style=cfg_style)
            highlighted = highlight(code, lexer, formatter)
            if cfg_style == "monokai" and cfg_formatter == "terminal256":
                highlighted = highlighted.replace("\x1b[38;5;245m", "\x1b[38;5;242m")
                highlighted = highlighted.replace("\x1b[38;5;15m", "\x1b[38;5;231m")
                highlighted = highlighted.replace("\x1b[38;5;255m", "\x1b[38;5;231m")
                highlighted = highlighted.replace("\x1b[37m", "\x1b[38;5;231m")
                highlighted = highlighted.replace("\x1b[39m", "\x1b[0m")
            sys.stdout.write(highlighted)
            return
        except Exception:
            pass
        out_lines = []
        for line in content.splitlines():
            if line.lstrip().startswith('#'):
                out_lines.append(f"\x1b[38;5;242m{line}\x1b[0m\x1b[38;5;231m\x1b[0m")
            else:
                if line == "":
                    out_lines.append(f"\x1b[38;5;231m\x1b[0m")
                else:
                    out_lines.append(f"\x1b[38;5;231m{line}\x1b[0m")
        sys.stdout.write("\n".join(out_lines) + "\n")
        return
    sys.stdout.write(content)
    if content and not content.endswith('\n'):
        sys.stdout.write('\n')

def handle_search(sheets, cfg, phrase, colorize=False, regex=False):
    flags = 0
    if not regex:
        flags = re.IGNORECASE
    try:
        pattern = re.compile(phrase, flags)
    except re.error as e:
        sys.stderr.write(f"failed to search: {e}\n")
        sys.exit(1)
    matching_sheets = []
    for s in sheets:
        if pattern.search(s["content"]):
            matching_sheets.append(s)
    matching_sheets_sorted = sorted(matching_sheets, key=lambda x: x["title"].lower())
    for s in matching_sheets_sorted:
        tags_str = ",".join(s["tags"])
        if colorize or cfg.get("colorize", False):
            sys.stdout.write(f"{s['title']} \x1b[2m({tags_str})\x1b[0m\n")
            for line in s["content"].splitlines():
                if line.lstrip().startswith('#'):
                    colored = f"\x1b[38;5;242m{line}\x1b[0m\x1b[38;5;231m\x1b[0m"
                else:
                    colored = f"\x1b[38;5;231m{line}\x1b[0m" if line else f"\x1b[38;5;231m\x1b[0m"
                sys.stdout.write(f"\t{colored}\n")
        else:
            sys.stdout.write(f"{s['title']} ({tags_str})\n")
            for line in s["content"].splitlines():
                sys.stdout.write(f"\t{line}\n")

def main():
    args = sys.argv[1:]
    if "-h" in args or "--help" in args:
        print("""cheat allows you to create and view interactive cheatsheets on the
command-line. It was designed to help remind *nix system administrators of
options for commands that they use frequently, but not frequently enough to
remember.

Usage:
  cheat [cheatsheet] [flags]

Examples:
  To initialize a config file:
    mkdir -p ~/.config/cheat && cheat --init > ~/.config/cheat/conf.yml

  To view the tar cheatsheet:
    cheat tar

  To edit (or create) the foo cheatsheet:
    cheat -e foo

  To edit (or create) the foo/bar cheatsheet on the "work" cheatpath:
    cheat -p work -e foo/bar

  To view all cheatsheet directories:
    cheat -d

  To list all available cheatsheets:
    cheat -l

  To briefly list all cheatsheets whose titles match "apt":
    cheat -b apt

  To list all tags in use:
    cheat -T

  To list available cheatsheets that are tagged as "personal":
    cheat -l -t personal

  To search for "ssh" among all cheatsheets, and colorize matches:
    cheat -c -s ssh

  To search (by regex) for cheatsheets that contain an IP address:
    cheat -c -r -s '(?:[0-9]{1,3}\\.){3}[0-9]{1,3}'

  To remove (delete) the foo/bar cheatsheet:
    cheat --rm foo/bar

  To update all git-backed cheatpaths:
    cheat --update

