def parse_config_simple(text):
    result = {}
    cheatpaths = []
    current = None
    in_cheatpaths = False
    for raw_line in text.splitlines():
        stripped = raw_line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        if stripped == '---':
            continue
        if stripped.startswith('cheatpaths:'):
            in_cheatpaths = True
            result['cheatpaths'] = cheatpaths
            continue
        if in_cheatpaths:
            if raw_line.lstrip().startswith('-'):
                current = {}
                cheatpaths.append(current)
                after_dash = raw_line.lstrip()[1:].strip()
                if after_dash and ':' in after_dash:
                    k,v = after_dash.split(':',1)
                    k=k.strip()
                    v=v.strip()
                    if v.startswith('[') and v.endswith(']'):
                        inner = v[1:-1].strip()
                        if not inner:
                            current[k]=[]
                        else:
                            parts = [p.strip() for p in inner.split(',')]
                            cleaned=[]
                            for p in parts:
                                if (p.startswith('"') and p.endswith('"')) or (p.startswith("'") and p.endswith("'")):
                                    p=p[1:-1]
                                cleaned.append(p)
                            current[k]=cleaned
                    else:
                        if v.lower() == 'true':
                            current[k]=True
                        elif v.lower() == 'false':
                            current[k]=False
                        else:
                            if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                                v=v[1:-1]
                            current[k]=v
                continue
            else:
                if current is None:
                    continue
                if ':' not in raw_line:
                    continue
                k,v = raw_line.split(':',1)
                k=k.strip()
                v=v.strip()
                if v.startswith('[') and v.endswith(']'):
                    inner = v[1:-1].strip()
                    if not inner:
                        current[k]=[]
                    else:
                        parts = [p.strip() for p in inner.split(',')]
                        cleaned=[]
                        for p in parts:
                            if (p.startswith('"') and p.endswith('"')) or (p.startswith("'") and p.endswith("'")):
                                p=p[1:-1]
                            cleaned.append(p)
                        current[k]=cleaned
                else:
                    if v.lower() == 'true':
                        current[k]=True
                    elif v.lower() == 'false':
                        current[k]=False
                    else:
                        if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                            v=v[1:-1]
                        current[k]=v
        else:
            if ':' not in raw_line:
                continue
            k,v = raw_line.split(':',1)
            k=k.strip()
            v=v.strip()
