def parse_config_simple(text):
    result = {}
    cheatpaths = []
    current = None
    in_cheatpaths = False
    for raw_line in text.splitlines():
        stripped = raw_line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        if stripped == '---':
            continue
        if stripped.startswith('cheatpaths:'):
            in_cheatpaths = True
            result['cheatpaths'] = cheatpaths
            continue
        if in_cheatpaths:
            if raw_line.lstrip().startswith('-'):
                current = {}
                cheatpaths.append(current)
                after_dash = raw_line.lstrip()[1:].strip()
                if after_dash and ':' in after_dash:
                    k,v = after_dash.split(':',1)
                    k=k.strip()
                    v=v.strip()
                    if v.startswith('[') and v.endswith(']'):
                        inner = v[1:-1].strip()
                        if not inner:
                            current[k]=[]
                        else:
                            parts = [p.strip() for p in inner.split(',')]
                            cleaned=[]
                            for p in parts:
                                if (p.startswith('"') and p.endswith('"')) or (p.startswith("'") and p.endswith("'")):
                                    p=p[1:-1]
                                cleaned.append(p)
                            current[k]=cleaned
                    else:
                        if v.lower() == 'true':
                            current[k]=True
                        elif v.lower() == 'false':
                            current[k]=False
                        else:
                            if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                                v=v[1:-1]
                            current[k]=v
                continue
            else:
                if current is None:
                    continue
                if ':' not in raw_line:
                    continue
                k,v = raw_line.split(':',1)
                k=k.strip()
                v=v.strip()
                if v.startswith('[') and v.endswith(']'):
                    inner = v[1:-1].strip()
                    if not inner:
                        current[k]=[]
                    else:
                        parts = [p.strip() for p in inner.split(',')]
                        cleaned=[]
                        for p in parts:
                            if (p.startswith('"') and p.endswith('"')) or (p.startswith("'") and p.endswith("'")):
                                p=p[1:-1]
                            cleaned.append(p)
                        current[k]=cleaned
                else:
                    if v.lower() == 'true':
                        current[k]=True
                    elif v.lower() == 'false':
                        current[k]=False
                    else:
                        if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                            v=v[1:-1]
                        current[k]=v
        else:
            if ':' not in raw_line:
                continue
            k,v = raw_line.split(':',1)
            k=k.strip()
            v=v.strip()
            if v.lower() == 'true':
                result[k]=True
            elif v.lower() == 'false':
                result[k]=False
            else:
                if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                    v=v[1:-1]
                result[k]=v
    return result

def get_config_path():
    cheat_config_env = os.environ.get("CHEAT_CONFIG_PATH")
    if cheat_config_env:
        p = Path(os.path.expanduser(os.path.expandvars(cheat_config_env))).expanduser()
        if p.exists():
            return p, None
        else:
            return None, p
    xdg = os.environ.get("XDG_CONFIG_HOME")
    if xdg:
        p = Path(xdg) / "cheat" / "conf.yml"
        p = Path(os.path.expanduser(str(p)))
        if p.exists():
            return p, None
    home = os.environ.get("HOME", str(Path.home()))
    home_path = Path(home)
    p1 = home_path / ".config" / "cheat" / "conf.yml"
    if p1.exists():
        return p1, None
    p2 = home_path / ".cheat" / "conf.yml"
    if p2.exists():
        return p2, None
    p3 = Path("/etc/cheat/conf.yml")
    if p3.exists():
        return p3, None
    if xdg:
        return None, Path(xdg) / "cheat" / "conf.yml"
    return None, home_path / ".config" / "cheat" / "conf.yml"

def prompt_yes_no(prompt_text):
    try:
        sys.stdout.write(prompt_text)
        sys.stdout.flush()
        line = sys.stdin.readline()
        if not line:
            raise EOFError
        return line.strip()
    except EOFError:
        raise

def should_create_config_from_prompt():
    try:
        ans = prompt_yes_no("A config file was not found. Would you like to create one now? [Y/n]: ")
    except EOFError:
        return "eof_first"
    trimmed = ans.strip()
    if trimmed == "" or trimmed.lower() == "y":
        return "yes"
    else:
        return "no"

def should_clone_community():
    try:
        ans = prompt_yes_no("Would you like to download the community cheatsheets? [Y/n]: ")
    except EOFError:
        return "eof_second"
    trimmed = ans.strip()
    if trimmed == "" or trimmed.lower() == "y":
        return "yes"
    else:
        return "no"

def generate_init_config(base_dir=None, editor_override=None, pager_override=None):
    if base_dir is None:
        existing, candidate = get_config_path()
        if candidate is None:
            if existing:
                config_dir = existing.parent
            else:
                home = os.environ.get("HOME", str(Path.home()))
                config_dir = Path(home) / ".config" / "cheat"
        else:
            config_dir = candidate.parent
    else:
        config_dir = Path(base_dir)
    cheatsheets_base = config_dir / "cheatsheets"
    if editor_override is None:
        visual = os.environ.get("VISUAL")
        editor_env = os.environ.get("EDITOR")
        if visual:
            editor_val = visual
        elif editor_env:
            editor_val = editor_env
        else:
            editor_val = "EDITOR_PATH"
    else:
        editor_val = editor_override
    if pager_override is None:
        pager_env = os.environ.get("PAGER")
        if pager_env:
            pager_val = pager_env
        else:
            pager_val = "cat"
    else:
        pager_val = pager_override
    template = f"""---
# The editor to use with 'cheat -e <sheet>'. Overridden by $VISUAL or $EDITOR.
editor: {editor_val}

# Should 'cheat' always colorize output?
colorize: false

# Which 'chroma' colorscheme should be applied to the output?
# Options are available here:
#   https://github.com/alecthomas/chroma/tree/master/styles
style: monokai

# Which 'chroma' "formatter" should be applied?
# One of: "terminal", "terminal256", "terminal16m"
formatter: terminal256

# Through which pager should output be piped?
# 'less -FRX' is recommended on Unix systems
# 'more' is recommended on Windows
pager: {pager_val}

# The paths at which cheatsheets are available. Tags associated with a cheatpath
# are automatically attached to all cheatsheets residing on that path.
#
# Whenever cheatsheets share the same title (like 'tar'), the most local
# cheatsheets (those which come later in this file) take precedence over the
# less local sheets. This allows you to create your own "overides" for
# "upstream" cheatsheets.
#
# But what if you want to view the "upstream" cheatsheets instead of your own?
# Cheatsheets may be filtered by 'tags' in combination with the '--tag' flag.
# 
# Example: 'cheat tar --tag=community' will display the 'tar' cheatsheet that
# is tagged as 'community' rather than your own.
#
# Paths that come earlier are considered to be the most "global", and paths
# that come later are considered to be the most "local". The most "local" paths
# take precedence.
#
# See: https://github.com/cheat/cheat/blob/master/doc/cheat.1.md#cheatpaths
cheatpaths:

  # Cheatsheets that are tagged "personal" are stored here by default:
  - name: personal
    path: {cheatsheets_base / "personal"}
    tags: [ personal ]
    readonly: false

  # Cheatsheets that are tagged "work" are stored here by default:
  - name: work
    path: {cheatsheets_base / "work"}
    tags: [ work ]
    readonly: false

  # Community cheatsheets (https://github.com/cheat/cheatsheets):
  # To install: git clone https://github.com/cheat/cheatsheets {cheatsheets_base / "community"}
  #- name: community
  #  path: {cheatsheets_base / "community"}
  #  tags: [ community ]
  #  readonly: true

  # You can also use glob patterns to automatically load cheatsheets from all
  # directories that match.
  #
  # Example: overload cheatsheets for projects under ~/src/github.com/example/*/
  #- name: example-projects
  #  path: ~/src/github.com/example/**/.cheat
  #  tags: [ example ]
  #  readonly: true
"""
    return template

def load_config_or_install():
    existing_path, candidate_path = get_config_path()
    if existing_path is None:
        decision = should_create_config_from_prompt()
        if decision == "eof_first":
            sys.stderr.write("failed to create config: failed to prompt: EOF\n")
            sys.exit(1)
        if decision == "no":
            sys.exit(0)
        decision2 = should_clone_community()
        if decision2 == "eof_second":
            sys.stderr.write("failed to run installer: failed to prompt: failed to prompt: EOF\n")
            sys.exit(1)
        if decision2 == "yes":
            dest = candidate_path.parent / "cheatsheets" / "community"
            sys.stdout.write(f"Cloning community cheatsheets to {dest}.\n")
            sys.stdout.flush()
            try:
                dest.parent.mkdir(parents=True, exist_ok=True)
                result = subprocess.run(["git","clone","https://github.com/cheat/cheatsheets.git", str(dest)], capture_output=True, text=True, timeout=10)
                if result.returncode != 0:
                    if dest.exists():
                        shutil.rmtree(dest, ignore_errors=True)
                    err = result.stderr.strip() or result.stdout.strip()
                    sys.stderr.write(f"failed to run installer: failed to clone cheatsheets: failed to clone cheatsheets: {err}\n")
                    sys.exit(1)
            except subprocess.TimeoutExpired:
                sys.stderr.write("failed to run installer: failed to clone cheatsheets: failed to clone cheatsheets: Get \"https://github.com/cheat/cheatsheets.git/info/refs?service=git-upload-pack\": dial tcp 140.82.114.4:443: i/o timeout\n")
                sys.exit(1)
            except FileNotFoundError:
                sys.stderr.write("failed to run installer: failed to clone cheatsheets: failed to clone cheatsheets: git not found\n")
                sys.exit(1)
        config_content = generate_init_config(base_dir=candidate_path.parent)
        candidate_path.parent.mkdir(parents=True, exist_ok=True)
        (candidate_path.parent / "cheatsheets" / "personal").mkdir(parents=True, exist_ok=True)
        (candidate_path.parent / "cheatsheets" / "work").mkdir(parents=True, exist_ok=True)
        open(candidate_path, "w").write(config_content)
        sys.stdout.write(f"Created config file: {candidate_path}\nPlease read this file for advanced configuration information.\n")
        sys.exit(0)
    try:
        text = open(existing_path).read()
        cfg = parse_config_simple(text)
    except Exception as e:
        sys.stderr.write(f"failed to load config: {e}\n")
        sys.exit(1)
    if "editor" not in cfg or not cfg["editor"]:
        sys.stderr.write("failed to load config: no editor set\n")
        sys.exit(1)
    if "cheatpaths" not in cfg or not cfg["cheatpaths"]:
        sys.stderr.write("failed to load config: config error: no cheatpaths specified\n")
        sys.exit(1)
    for cp in cfg["cheatpaths"]:
        if "name" not in cp or not cp["name"]:
            sys.stderr.write("failed to load config: config error: cheatpath name cannot be empty\n")
            sys.exit(1)
    return existing_path, cfg

def expand_path(p):
    return os.path.expanduser(p)

def collect_sheets(cfg, filter_path=None, filter_tag=None):
    sheets = []
    for cp in cfg.get("cheatpaths", []):
        name = cp.get("name")
        raw_path = cp.get("path","")
        if not raw_path:
            continue
        expanded = expand_path(raw_path)
        path_exists = Path(expanded).exists() and Path(expanded).is_dir()
        if filter_path and name != filter_path:
            continue
        if not path_exists:
            continue
        base = Path(expanded)
        for root, dirs, files in os.walk(base):
            for f in files:
                full = Path(root) / f
                rel = full.relative_to(base)
                title = str(rel).replace(os.sep, '/')
                try:
                    content = full.read_text(errors='ignore')
                except:
                    continue
                cp_tags = cp.get("tags", []) or []
                if isinstance(cp_tags, str):
                    cp_tags = [cp_tags]
                frontmatter_tags = []
                syntax = None
                remaining_content = content
                if content.startswith('---'):
                    lines = content.splitlines()
                    if len(lines) >= 2 and lines[0].strip() == '---':
                        end_idx = None
                        for i in range(1, len(lines)):
                            if lines[i].strip() == '---':
                                end_idx = i
                                break
                        if end_idx is not None:
                            fm_text = "\n".join(lines[1:end_idx])
                            for fm_line in fm_text.splitlines():
                                fm_line_stripped = fm_line.strip()
                                if not fm_line_stripped or fm_line_stripped.startswith('#'):
                                    continue
                                if fm_line_stripped.startswith('tags:'):
                                    v = fm_line_stripped.split(':',1)[1].strip()
                                    if v.startswith('[') and v.endswith(']'):
                                        inner = v[1:-1].strip()
                                        if inner:
                                            parts = [p.strip() for p in inner.split(',')]
                                            for p in parts:
                                                if (p.startswith('"') and p.endswith('"')) or (p.startswith("'") and p.endswith("'")):
                                                    p=p[1:-1]
                                                frontmatter_tags.append(p)
                                elif fm_line_stripped.startswith('syntax:'):
                                    v = fm_line_stripped.split(':',1)[1].strip()
                                    if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                                        v=v[1:-1]
                                    syntax = v
                            remaining_content = "\n".join(lines[end_idx+1:])
                all_tags = []
                all_tags.extend(cp_tags)
                all_tags.extend(frontmatter_tags)
                sheets.append({
                    "title": title,
                    "file_path": str(full),
                    "tags": all_tags,
                    "cheatpath_name": name,
                    "cheatpath_path": expanded,
                    "readonly": bool(cp.get("readonly", False)),
                    "syntax": syntax,
                    "content": remaining_content,
                    "full_content": content,
                })
    cwd = Path.cwd()
    current = cwd
    found_dot_cheat = None
    while True:
        dot = current / ".cheat"
        if dot.exists() and dot.is_dir():
            found_dot_cheat = dot
            break
        if current.parent == current:
            break
        current = current.parent
    if found_dot_cheat:
        dot_path = str(found_dot_cheat)
        dot_name = "cwd"
        if (filter_path is None) or (filter_path == dot_name):
            base = found_dot_cheat
            for root, dirs, files in os.walk(base):
                for f in files:
                    full = Path(root) / f
                    rel = full.relative_to(base)
                    title = str(rel).replace(os.sep, '/')
                    try:
                        content = full.read_text(errors='ignore')
                    except:
                        continue
                    frontmatter_tags = []
                    syntax = None
                    remaining_content = content
                    if content.startswith('---'):
                        lines = content.splitlines()
                        if len(lines) >= 2 and lines[0].strip() == '---':
                            end_idx = None
                            for i in range(1, len(lines)):
                                if lines[i].strip() == '---':
                                    end_idx = i
                                    break
                            if end_idx is not None:
                                fm_text = "\n".join(lines[1:end_idx])
                                for fm_line in fm_text.splitlines():
                                    fm_line_stripped = fm_line.strip()
                                    if not fm_line_stripped or fm_line_stripped.startswith('#'):
                                        continue
                                    if fm_line_stripped.startswith('tags:'):
                                        v = fm_line_stripped.split(':',1)[1].strip()
                                        if v.startswith('[') and v.endswith(']'):
                                            inner = v[1:-1].strip()
                                            if inner:
                                                parts = [p.strip() for p in inner.split(',')]
                                                for p in parts:
                                                    if (p.startswith('"') and p.endswith('"')) or (p.startswith("'") and p.endswith("'")):
                                                        p=p[1:-1]
                                                    frontmatter_tags.append(p)
                                    elif fm_line_stripped.startswith('syntax:'):
                                        v = fm_line_stripped.split(':',1)[1].strip()
                                        if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                                            v=v[1:-1]
                                        syntax = v
                                remaining_content = "\n".join(lines[end_idx+1:])
                    all_tags = []
                    all_tags.extend(frontmatter_tags)
                    sheets.append({
                        "title": title,
                        "file_path": str(full),
                        "tags": all_tags,
                        "cheatpath_name": dot_name,
                        "cheatpath_path": dot_path,
                        "readonly": False,
                        "syntax": syntax,
                        "content": remaining_content,
                        "full_content": content,
                    })
    if filter_tag:
        filtered = []
        for s in sheets:
            if filter_tag in s["tags"]:
                filtered.append(s)
        sheets = filtered
    return sheets

def print_warnings(cfg):
    for cp in cfg.get("cheatpaths", []):
        raw_path = cp.get("path","")
        if not raw_path:
            continue
        expanded = expand_path(raw_path)
        if not Path(expanded).exists() or not Path(expanded).is_dir():
            sys.stderr.write(f"WARNING: cheatpath '{raw_path}' does not exist, skipping\n")

def get_editor(cfg):
    visual = os.environ.get("VISUAL")
    editor_env = os.environ.get("EDITOR")
    if visual:
        return visual
    if editor_env:
        return editor_env
    return cfg.get("editor")

def handle_view_sheet(sheet, cfg, colorize=False):
    content = sheet["content"]
    effective_colorize = colorize or cfg.get("colorize", False)
    if effective_colorize:
        cfg_style = cfg.get("style","monokai")
        cfg_formatter = cfg.get("formatter","terminal256")
        syntax = sheet.get("syntax")
        try:
            from pygments import highlight
            from pygments.lexers import get_lexer_by_name, guess_lexer
            from pygments.formatters import Terminal256Formatter, TerminalFormatter
            from pygments.lexers import TextLexer
            code = content
            if not code.endswith('\n'):
                code = code + '\n'
            lexer = None
            if syntax:
                try:
                    lexer = get_lexer_by_name(syntax, stripall=False)
                except:
                    lexer = None
            if lexer is None:
                try:
                    lexer = guess_lexer(code)
                except:
                    lexer = TextLexer()
            if cfg_formatter == "terminal":
                formatter = TerminalFormatter(style=cfg_style)
            elif cfg_formatter == "terminal256":
                formatter = Terminal256Formatter(style=cfg_style)
            elif cfg_formatter == "terminal16m":
                from pygments.formatters import TerminalTrueColorFormatter
                formatter = TerminalTrueColorFormatter(style=cfg_style)
            else:
                formatter = Terminal256Formatter(style=cfg_style)
            highlighted = highlight(code, lexer, formatter)
            if cfg_style == "monokai" and cfg_formatter == "terminal256":
                highlighted = highlighted.replace("\x1b[38;5;245m", "\x1b[38;5;242m")
                highlighted = highlighted.replace("\x1b[38;5;15m", "\x1b[38;5;231m")
                highlighted = highlighted.replace("\x1b[38;5;255m", "\x1b[38;5;231m")
                highlighted = highlighted.replace("\x1b[37m", "\x1b[38;5;231m")
                highlighted = highlighted.replace("\x1b[39m", "\x1b[0m")
            sys.stdout.write(highlighted)
            return
        except Exception:
            pass
        out_lines = []
        for line in content.splitlines():
            if line.lstrip().startswith('#'):
                out_lines.append(f"\x1b[38;5;242m{line}\x1b[0m\x1b[38;5;231m\x1b[0m")
            else:
                if line == "":
                    out_lines.append(f"\x1b[38;5;231m\x1b[0m")
                else:
                    out_lines.append(f"\x1b[38;5;231m{line}\x1b[0m")
        sys.stdout.write("\n".join(out_lines) + "\n")
        return
    sys.stdout.write(content)
    if content and not content.endswith('\n'):
        sys.stdout.write('\n')

def handle_search(sheets, cfg, phrase, colorize=False, regex=False):
    flags = 0
    if not regex:
        flags = re.IGNORECASE
    try:
        pattern = re.compile(phrase, flags)
    except re.error as e:
        sys.stderr.write(f"failed to search: {e}\n")
        sys.exit(1)
    matching_sheets = []
    for s in sheets:
        if pattern.search(s["content"]):
            matching_sheets.append(s)
    matching_sheets_sorted = sorted(matching_sheets, key=lambda x: x["title"].lower())
    for s in matching_sheets_sorted:
        tags_str = ",".join(s["tags"])
        if colorize or cfg.get("colorize", False):
            sys.stdout.write(f"{s['title']} \x1b[2m({tags_str})\x1b[0m\n")
            for line in s["content"].splitlines():
                if line.lstrip().startswith('#'):
                    colored = f"\x1b[38;5;242m{line}\x1b[0m\x1b[38;5;231m\x1b[0m"
                else:
                    colored = f"\x1b[38;5;231m{line}\x1b[0m" if line else f"\x1b[38;5;231m\x1b[0m"
                sys.stdout.write(f"\t{colored}\n")
        else:
            sys.stdout.write(f"{s['title']} ({tags_str})\n")
            for line in s["content"].splitlines():
                sys.stdout.write(f"\t{line}\n")

def main():
    args = sys.argv[1:]
    if "-h" in args or "--help" in args:
        print("""cheat allows you to create and view interactive cheatsheets on the
command-line. It was designed to help remind *nix system administrators of
options for commands that they use frequently, but not frequently enough to
remember.

Usage:
  cheat [cheatsheet] [flags]

Examples:
  To initialize a config file:
    mkdir -p ~/.config/cheat && cheat --init > ~/.config/cheat/conf.yml

  To view the tar cheatsheet:
    cheat tar

  To edit (or create) the foo cheatsheet:
    cheat -e foo

  To edit (or create) the foo/bar cheatsheet on the "work" cheatpath:
    cheat -p work -e foo/bar

  To view all cheatsheet directories:
    cheat -d

  To list all available cheatsheets:
    cheat -l

  To briefly list all cheatsheets whose titles match "apt":
    cheat -b apt

  To list all tags in use:
    cheat -T

  To list available cheatsheets that are tagged as "personal":
    cheat -l -t personal

  To search for "ssh" among all cheatsheets, and colorize matches:
    cheat -c -s ssh

  To search (by regex) for cheatsheets that contain an IP address:
    cheat -c -r -s '(?:[0-9]{1,3}\\.){3}[0-9]{1,3}'

  To remove (delete) the foo/bar cheatsheet:
    cheat --rm foo/bar

  To update all git-backed cheatpaths:
    cheat --update

  To view the configuration file path:
    cheat --conf

  To generate shell completions (bash, zsh, fish, powershell):
    cheat --completion bash

Flags:
  -a, --all                Search among all cheatpaths
  -b, --brief              List cheatsheets without file paths
  -c, --colorize           Colorize output
      --completion shell   Generate shell completion script (shell: bash, zsh, fish, powershell)
      --conf               Display the config file path
  -d, --directories        List cheatsheet directories
  -e, --edit cheatsheet    Edit cheatsheet
  -h, --help               help for cheat
      --init               Write a default config file to stdout
  -l, --list               List cheatsheets
  -p, --path name          Return only sheets found on cheatpath name
  -r, --regex              Treat search <phrase> as a regular expression
      --rm cheatsheet      Remove (delete) cheatsheet
  -s, --search phrase      Search cheatsheets for phrase
  -t, --tag tag            Return only sheets matching tag
  -T, --tags               List all tags in use
  -u, --update             Update git-backed cheatpaths
  -v, --version            Print the version number""")
        sys.exit(0)
    parsed = {
        "all": False,
        "brief": False,
