            sys.stderr.write(f"accepts at most 1 arg(s), received {len(parsed['positional'])}\n")
            sys.exit(1)
        title = parsed["positional"][0]
        sheets = collect_sheets(cfg, filter_path=parsed["path"], filter_tag=parsed["tag"])
        matching = [s for s in sheets if s["title"] == title]
        if not matching:
            print(f"No cheatsheet found for '{title}'.")
            sys.exit(2)
        if parsed["all"]:
            for idx, s in enumerate(matching):
                tags_str = ",".join(s["tags"])
                if parsed["colorize"] or cfg.get("colorize", False):
                    sys.stdout.write(f"{s['title']} \x1b[2m({tags_str})\x1b[0m\n")
                    for line in s["content"].splitlines():
                        if line.lstrip().startswith('#'):
                            colored = f"\x1b[38;5;242m{line}\x1b[0m\x1b[38;5;231m\x1b[0m"
                        else:
                            colored = f"\x1b[38;5;231m{line}\x1b[0m" if line else f"\x1b[38;5;231m\x1b[0m"
                        sys.stdout.write(f"\t{colored}\n")
                else:
                    sys.stdout.write(f"{s['title']} ({tags_str})\n")
                    for line in s["content"].splitlines():
                        sys.stdout.write(f"\t{line}\n")
                if idx != len(matching)-1:
                    sys.stdout.write("\n")
            sys.exit(0)
        else:
            most_local = matching[-1]
            handle_view_sheet(most_local, cfg, colorize=parsed["colorize"])
            sys.exit(0)

    if parsed["tag"]:
        sheets = collect_sheets(cfg, filter_path=parsed["path"], filter_tag=parsed["tag"])
        if not sheets:
            sys.exit(2)
        sheets_sorted = sorted(sheets, key=lambda x: x["title"].lower())
        max_title_len = max([len(s["title"]) for s in sheets_sorted] + [len("title:")])
        max_file_len = max([len(s["file_path"]) for s in sheets_sorted] + [len("file:")])
        title_width = max(len("title:"), max_title_len)
        file_width = max(len("file:"), max_file_len)
        header_title = "title:".ljust(title_width)
        header_file = "file:".ljust(file_width)
        sys.stdout.write(f"{header_title} {header_file} tags:\n")
        for s in sheets_sorted:
            title = s["title"]
            file_path = s["file_path"]
            tags_str = ",".join(s["tags"])
            title_padded = title.ljust(title_width)
            file_padded = file_path.ljust(file_width)
            sys.stdout.write(f"{title_padded} {file_padded} {tags_str}\n")
        sys.exit(0)

    print("""cheat allows you to create and view interactive cheatsheets on the
command-line. It was designed to help remind *nix system administrators of
options for commands that they use frequently, but not frequently enough to
remember.

Usage:
  cheat [cheatsheet] [flags]

Examples:
  To initialize a config file:
    mkdir -p ~/.config/cheat && cheat --init > ~/.config/cheat/conf.yml

  To view the tar cheatsheet:
    cheat tar

  To edit (or create) the foo cheatsheet:
    cheat -e foo

  To edit (or create) the foo/bar cheatsheet on the "work" cheatpath:
    cheat -p work -e foo/bar

  To view all cheatsheet directories:
    cheat -d

  To list all available cheatsheets:
    cheat -l

  To briefly list all cheatsheets whose titles match "apt":
    cheat -b apt

  To list all tags in use:
    cheat -T

  To list available cheatsheets that are tagged as "personal":
    cheat -l -t personal

  To search for "ssh" among all cheatsheets, and colorize matches:
    cheat -c -s ssh

  To search (by regex) for cheatsheets that contain an IP address:
    cheat -c -r -s '(?:[0-9]{1,3}\\.){3}[0-9]{1,3}'

  To remove (delete) the foo/bar cheatsheet:
    cheat --rm foo/bar

  To update all git-backed cheatpaths:
    cheat --update

  To view the configuration file path:
    cheat --conf

  To generate shell completions (bash, zsh, fish, powershell):
    cheat --completion bash

Flags:
  -a, --all                Search among all cheatpaths
  -b, --brief              List cheatsheets without file paths
  -c, --colorize           Colorize output
      --completion shell   Generate shell completion script (shell: bash, zsh, fish, powershell)
      --conf               Display the config file path
  -d, --directories        List cheatsheet directories
  -e, --edit cheatsheet    Edit cheatsheet
  -h, --help               help for cheat
      --init               Write a default config file to stdout
  -l, --list               List cheatsheets
  -p, --path name          Return only sheets found on cheatpath name
  -r, --regex              Treat search <phrase> as a regular expression
      --rm cheatsheet      Remove (delete) cheatsheet
  -s, --search phrase      Search cheatsheets for phrase
  -t, --tag tag            Return only sheets matching tag
  -T, --tags               List all tags in use
  -u, --update             Update git-backed cheatpaths
  -v, --version            Print the version number""")
    sys.exit(0)

if __name__ == "__main__":
    main()
