            continue
        if in_cheatpaths:
            if raw_line.lstrip().startswith('-'):
                current = {}
                cheatpaths.append(current)
                after_dash = raw_line.lstrip()[1:].strip()
                if after_dash and ':' in after_dash:
                    k,v = after_dash.split(':',1)
                    k=k.strip()
                    v=v.strip()
                    if v.startswith('[') and v.endswith(']'):
                        inner = v[1:-1].strip()
