  #  tags: [ example ]
  #  readonly: true
"""
    return template

def load_config_or_install():
    existing_path, candidate_path = get_config_path()
    if existing_path is None:
        decision = should_create_config_from_prompt()
        if decision == "eof_first":
            sys.stderr.write("failed to create config: failed to prompt: EOF\n")
            sys.exit(1)
        if decision == "no":
            sys.exit(0)
        decision2 = should_clone_community()
        if decision2 == "eof_second":
            sys.stderr.write("failed to run installer: failed to prompt: failed to prompt: EOF\n")
            sys.exit(1)
        if decision2 == "yes":
            dest = candidate_path.parent / "cheatsheets" / "community"
            sys.stdout.write(f"Cloning community cheatsheets to {dest}.\n")
            sys.stdout.flush()
            try:
                dest.parent.mkdir(parents=True, exist_ok=True)
                result = subprocess.run(["git","clone","https://github.com/cheat/cheatsheets.git", str(dest)], capture_output=True, text=True, timeout=10)
                if result.returncode != 0:
                    if dest.exists():
                        shutil.rmtree(dest, ignore_errors=True)
                    err = result.stderr.strip() or result.stdout.strip()
                    sys.stderr.write(f"failed to run installer: failed to clone cheatsheets: failed to clone cheatsheets: {err}\n")
                    sys.exit(1)
            except subprocess.TimeoutExpired:
                sys.stderr.write("failed to run installer: failed to clone cheatsheets: failed to clone cheatsheets: Get \"https://github.com/cheat/cheatsheets.git/info/refs?service=git-upload-pack\": dial tcp 140.82.114.4:443: i/o timeout\n")
                sys.exit(1)
            except FileNotFoundError:
                sys.stderr.write("failed to run installer: failed to clone cheatsheets: failed to clone cheatsheets: git not found\n")
                sys.exit(1)
        config_content = generate_init_config(base_dir=candidate_path.parent)
        candidate_path.parent.mkdir(parents=True, exist_ok=True)
        (candidate_path.parent / "cheatsheets" / "personal").mkdir(parents=True, exist_ok=True)
        (candidate_path.parent / "cheatsheets" / "work").mkdir(parents=True, exist_ok=True)
        open(candidate_path, "w").write(config_content)
        sys.stdout.write(f"Created config file: {candidate_path}\nPlease read this file for advanced configuration information.\n")
        sys.exit(0)
    try:
        text = open(existing_path).read()
        cfg = parse_config_simple(text)
    except Exception as e:
        sys.stderr.write(f"failed to load config: {e}\n")
        sys.exit(1)
    if "editor" not in cfg or not cfg["editor"]:
        sys.stderr.write("failed to load config: no editor set\n")
        sys.exit(1)
    if "cheatpaths" not in cfg or not cfg["cheatpaths"]:
        sys.stderr.write("failed to load config: config error: no cheatpaths specified\n")
        sys.exit(1)
    for cp in cfg["cheatpaths"]:
        if "name" not in cp or not cp["name"]:
            sys.stderr.write("failed to load config: config error: cheatpath name cannot be empty\n")
            sys.exit(1)
    return existing_path, cfg

def expand_path(p):
    return os.path.expanduser(p)

def collect_sheets(cfg, filter_path=None, filter_tag=None):
    sheets = []
    for cp in cfg.get("cheatpaths", []):
        name = cp.get("name")
        raw_path = cp.get("path","")
        if not raw_path:
            continue
        expanded = expand_path(raw_path)
        path_exists = Path(expanded).exists() and Path(expanded).is_dir()
        if filter_path and name != filter_path:
            continue
        if not path_exists:
            continue
        base = Path(expanded)
        for root, dirs, files in os.walk(base):
            for f in files:
                full = Path(root) / f
                rel = full.relative_to(base)
                title = str(rel).replace(os.sep, '/')
                try:
                    content = full.read_text(errors='ignore')
                except:
                    continue
                cp_tags = cp.get("tags", []) or []
                if isinstance(cp_tags, str):
                    cp_tags = [cp_tags]
                frontmatter_tags = []
