                remaining_content = content
                if content.startswith('---'):
                    lines = content.splitlines()
                    if len(lines) >= 2 and lines[0].strip() == '---':
                        end_idx = None
                        for i in range(1, len(lines)):
                            if lines[i].strip() == '---':
                                end_idx = i
                                break
                        if end_idx is not None:
                            fm_text = "\n".join(lines[1:end_idx])
